#[derive(Debug, Deserialize, Serialize, JsonSchema, Validate, Clone, PartialEq, Eq, Default, Hash)]
pub struct Filter {
    /// At least one of those conditions should match
    #[validate(nested)]
    pub should: Option<Vec<Condition>>,  // <-- Option means null is VALID
    /// All conditions must match
    #[validate(nested)]
    pub must: Option<Vec<Condition>>,
    /// All conditions must NOT match
    #[validate(nested)]
    pub must_not: Option<Vec<Condition>>,
}

